// HasInvoice applies the HasEdge predicate on the "invoice" edge.
func HasInvoice() predicate.FinanceInvoiceFeeAllocation {
	return predicate.FinanceInvoiceFeeAllocation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, InvoiceTable, InvoiceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasInvoiceWith applies the HasEdge predicate on the "invoice" edge with a given conditions (other predicates).
func HasInvoiceWith(preds ...predicate.FinanceInvoice) predicate.FinanceInvoiceFeeAllocation {
	return predicate.FinanceInvoiceFeeAllocation(func(s *sql.Selector) {
		step := newInvoiceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

